"""Tests for src/textstats.py."""

import os
import sys

import pytest

sys.path.insert(0, os.path.join(os.path.dirname(__file__), "..", "src"))

import textstats  # noqa: E402


def test_normalize_lowercases_and_strips_punctuation():
    assert textstats.normalize("Hello, World!") == "hello world"


def test_normalize_collapses_whitespace():
    assert textstats.normalize("  a\t b\n\nc  ") == "a b c"


def test_normalize_empty_and_punctuation_only():
    assert textstats.normalize("") == ""
    assert textstats.normalize("   ") == ""
    assert textstats.normalize("!!! ... ???") == ""


def test_normalize_rejects_non_str():
    with pytest.raises(TypeError):
        textstats.normalize(123)


def test_word_frequencies_counts_and_orders():
    text = "the cat the dog the bird cat"
    assert textstats.word_frequencies(text) == {
        "the": 3,
        "cat": 2,
        "bird": 1,
        "dog": 1,
    }


def test_word_frequencies_tie_break_alphabetical():
