    text = "dog cat bird dog cat bird"
    assert top_words(text, 3) == [("bird", 2), ("cat", 2), ("dog", 2)]


def test_top_words_strips_punctuation_and_case():
    text = "Hello, hello! HELLO world."
    assert top_words(text, 2) == [("hello", 3), ("world", 1)]


