    return tokens


def word_counts(text: str) -> dict[str, int]:
    """Return a token -> count mapping in first-seen order."""
    counts: dict[str, int] = {}
    for token in normalize(text):
        counts[token] = counts.get(token, 0) + 1
    return counts


def top_words(text: str, n: int = 3) -> list[tuple[str, int]]:
    """Return the ``n`` most frequent tokens as ``(token, count)`` tuples.

    Ties are broken by first appearance order, then alphabetically for
    determinism. ``n <= 0`` yields an empty list; ``n`` larger than the number
    of distinct tokens simply returns all of them.
    """
    if not isinstance(n, int) or isinstance(n, bool):
        raise TypeError("n must be an int")
    if n <= 0:
        return []

    counts = word_counts(text)
    first_seen = {token: index for index, token in enumerate(counts)}
    ordered = sorted(
        counts.items(),
        key=lambda item: (-item[1], first_seen[item[0]], item[0]),
    )
    return ordered[:n]


def unique_word_count(text: str) -> int:
    """Return the number of distinct tokens in ``text``."""
    return len(word_counts(text))

